-- =============================================================================
-- CleanOps — initial schema
-- Target: Supabase (Postgres 15+). Money is ALWAYS integer cents. Times are
-- timestamptz; the business runs in America/New_York (see app config BUSINESS_TZ).
--
-- Apply with the Supabase CLI (supabase db push) or paste into the SQL editor.
-- Do not edit this file after it has been applied; add 0002_*.sql instead.
-- =============================================================================

create extension if not exists pgcrypto;

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
create type client_type        as enum ('residential', 'commercial');
create type client_status      as enum ('lead', 'active', 'inactive');
create type lead_status        as enum ('new', 'contacted', 'quoted', 'won', 'lost');
create type proposal_status    as enum ('draft', 'sent', 'accepted', 'declined', 'expired');
create type job_status         as enum ('scheduled', 'confirmed', 'in_progress', 'done', 'cancelled', 'skipped');
create type assignment_status  as enum ('offered', 'accepted', 'declined', 'done', 'no_show');
create type charge_method      as enum ('stripe_card', 'stripe_ach', 'stripe_invoice', 'zelle', 'check', 'cash');
create type payout_method      as enum ('zelle', 'cash', 'check', 'other');
create type invoice_status     as enum ('draft', 'sent', 'paid', 'void', 'uncollectible');
create type expense_cadence    as enum ('one_time', 'weekly', 'monthly', 'quarterly', 'annual');
create type expense_category   as enum ('overhead', 'software', 'ads', 'supplies', 'insurance', 'other');
create type message_channel    as enum ('sms', 'email');
create type message_status     as enum ('queued', 'sent', 'delivered', 'failed');
create type user_role          as enum ('owner', 'provider');

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------
create or replace function set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- -----------------------------------------------------------------------------
-- People
-- -----------------------------------------------------------------------------
create table profiles (
  user_id     uuid primary key references auth.users(id) on delete cascade,
  role        user_role not null default 'owner',
  full_name   text,
  created_at  timestamptz not null default now()
);

-- Cleaners / subcontractors
create table providers (
  id                 uuid primary key default gen_random_uuid(),
  name               text not null,
  phone              text,
  email              text,
  zelle_handle       text,                       -- phone or email they receive Zelle at
  default_pay_cents  integer check (default_pay_cents is null or default_pay_cents >= 0),
  service_area       text,
  w9_on_file         boolean not null default false,
  active             boolean not null default true,
  notes              text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create trigger providers_updated before update on providers for each row execute function set_updated_at();

create table clients (
  id                      uuid primary key default gen_random_uuid(),
  name                    text not null,
  type                    client_type not null default 'residential',
  status                  client_status not null default 'active',
  email                   text,
  phone                   text,
  default_charge_method   charge_method,
  stripe_customer_id      text unique,
  basic_info              text,                   -- the "Basic Info" column from the old sheet
  source                  text,                   -- where they came from (referral, Google, Yelp...)
  notes                   text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now()
);
create trigger clients_updated before update on clients for each row execute function set_updated_at();

-- A client can have several locations (home + office, multiple units).
create table locations (
  id                 uuid primary key default gen_random_uuid(),
  client_id          uuid not null references clients(id) on delete cascade,
  label              text not null default 'Main',
  address_line1      text,
  address_line2      text,
  city               text,
  state              text,
  postal_code        text,
  sqft               integer,
  bedrooms           numeric(4,1),
  bathrooms          numeric(4,1),
  scope_of_work      text,                        -- the "Scope of Work" column
  access_notes       text,                        -- parking, alarm, pets (NOT the code itself)
  lockbox_code_enc   text,                        -- AES-256-GCM ciphertext, encrypted by the app
  lockbox_hint       text,                        -- e.g. "lockbox on back gate"
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index locations_client_idx on locations(client_id);
create trigger locations_updated before update on locations for each row execute function set_updated_at();

-- -----------------------------------------------------------------------------
-- Services & pricing
-- -----------------------------------------------------------------------------
create table service_types (
  id                   uuid primary key default gen_random_uuid(),
  name                 text not null unique,          -- Standard, Deep, Move-out, Commercial, Post-construction
  default_duration_min integer not null default 120,
  active               boolean not null default true
);

-- Simple rate card so residential quotes can be produced without a walkthrough.
create table rate_cards (
  id                   uuid primary key default gen_random_uuid(),
  service_type_id      uuid not null references service_types(id) on delete cascade,
  client_type          client_type not null default 'residential',
  base_cents           integer not null default 0,
  per_bedroom_cents    integer not null default 0,
  per_bathroom_cents   integer not null default 0,
  per_sqft_cents       integer not null default 0,    -- usually 0 for residential, used for commercial
  min_charge_cents     integer not null default 0,
  target_margin_pct    numeric(5,2) not null default 40.00,  -- used to suggest provider pay
  active               boolean not null default true,
  unique (service_type_id, client_type)
);

-- -----------------------------------------------------------------------------
-- Sales: leads & proposals
-- -----------------------------------------------------------------------------
create table leads (
  id            uuid primary key default gen_random_uuid(),
  client_id     uuid references clients(id) on delete set null,   -- set once the lead becomes a client
  name          text not null,
  phone         text,
  email         text,
  client_type   client_type not null default 'residential',
  source        text,
  status        lead_status not null default 'new',
  lost_reason   text,
  intake        jsonb,            -- answers from the intake form (bedrooms, baths, sqft, add-ons, photos)
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create trigger leads_updated before update on leads for each row execute function set_updated_at();

create table proposals (
  id               uuid primary key default gen_random_uuid(),
  lead_id          uuid references leads(id) on delete set null,
  client_id        uuid references clients(id) on delete set null,
  title            text not null,
  status           proposal_status not null default 'draft',
  current_version  integer not null default 0,
  sent_at          timestamptz,
  decided_at       timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  check (lead_id is not null or client_id is not null)
);
create trigger proposals_updated before update on proposals for each row execute function set_updated_at();

-- Every regeneration or manual edit creates a new version; nothing is overwritten.
create table proposal_versions (
  id              uuid primary key default gen_random_uuid(),
  proposal_id     uuid not null references proposals(id) on delete cascade,
  version_no      integer not null,
  fields          jsonb not null,      -- structured, editable: scope_lines[], frequency, price_per_visit_cents, add_ons[], terms, start_date...
  rendered_md     text not null,       -- the proposal as markdown, rendered from the template + fields
  source_notes    text,                -- the Granola / walkthrough notes this version was generated from
  generated_by    text not null default 'manual',   -- 'claude' | 'manual'
  model           text,                -- model id when generated_by = 'claude'
  change_summary  text,                -- "raised price per visit to $450", "removed window add-on"
  created_at      timestamptz not null default now(),
  unique (proposal_id, version_no)
);

-- -----------------------------------------------------------------------------
-- Scheduling
-- -----------------------------------------------------------------------------
-- A recurring series (template). Instances are generated into `jobs`.
create table job_series (
  id                   uuid primary key default gen_random_uuid(),
  client_id            uuid not null references clients(id) on delete cascade,
  location_id          uuid not null references locations(id) on delete cascade,
  service_type_id      uuid not null references service_types(id),
  rrule                text not null,              -- RFC 5545, e.g. FREQ=WEEKLY;INTERVAL=2;BYDAY=TU
  start_date           date not null,
  end_date             date,
  start_time           time not null,              -- local time in BUSINESS_TZ
  duration_min         integer not null default 120,
  charge_cents         integer not null check (charge_cents >= 0),
  provider_pay_cents   integer not null check (provider_pay_cents >= 0),
  default_provider_id  uuid references providers(id) on delete set null,
  charge_method        charge_method,
  notes                text,
  active               boolean not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create index job_series_client_idx on job_series(client_id);
create trigger job_series_updated before update on job_series for each row execute function set_updated_at();

create table jobs (
  id                 uuid primary key default gen_random_uuid(),
  series_id          uuid references job_series(id) on delete set null,
  client_id          uuid not null references clients(id) on delete restrict,
  location_id        uuid not null references locations(id) on delete restrict,
  service_type_id    uuid not null references service_types(id),
  scheduled_start    timestamptz not null,
  duration_min       integer not null default 120,
  status             job_status not null default 'scheduled',
  charge_cents       integer not null check (charge_cents >= 0),
  charge_method      charge_method,
  notes              text,                       -- the old "Notes" column
  completed_at       timestamptz,
  completion_notes   text,                       -- what the cleaner reported
  photo_paths        text[] not null default '{}', -- Supabase Storage object paths
  cancelled_reason   text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index jobs_start_idx on jobs(scheduled_start);
create index jobs_client_idx on jobs(client_id);
create index jobs_status_idx on jobs(status);
-- One instance per series per local calendar day, so generation is idempotent.
create unique index jobs_series_day_uq
  on jobs (series_id, ((scheduled_start at time zone 'America/New_York')::date))
  where series_id is not null;
create trigger jobs_updated before update on jobs for each row execute function set_updated_at();

-- Who is doing the job and what they get paid. One job can have more than one
-- cleaner (big commercial jobs); each assignment is paid exactly once.
create table payouts (
  id            uuid primary key default gen_random_uuid(),
  provider_id   uuid not null references providers(id) on delete restrict,
  total_cents   integer not null default 0,          -- maintained by trigger from assignments
  method        payout_method not null default 'zelle',
  reference     text,                                -- Zelle confirmation number / memo
  paid_at       timestamptz,                         -- null = batch drafted but not yet sent
  notes         text,
  created_at    timestamptz not null default now()
);
create index payouts_provider_idx on payouts(provider_id);

create table job_assignments (
  id            uuid primary key default gen_random_uuid(),
  job_id        uuid not null references jobs(id) on delete cascade,
  provider_id   uuid not null references providers(id) on delete restrict,
  pay_cents     integer not null check (pay_cents >= 0),
  status        assignment_status not null default 'offered',
  payout_id     uuid references payouts(id) on delete set null,   -- set once included in a payout batch
  accepted_at   timestamptz,
  done_at       timestamptz,
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (job_id, provider_id)
);
create index job_assignments_job_idx on job_assignments(job_id);
create index job_assignments_provider_idx on job_assignments(provider_id);
create index job_assignments_unpaid_idx on job_assignments(provider_id) where payout_id is null;
create trigger job_assignments_updated before update on job_assignments for each row execute function set_updated_at();

-- Guard rails for the payout ledger:
--  1. An assignment can only be added to a payout for the same provider.
--  2. Once a payout is marked paid, its assignments are frozen.
--  3. payouts.total_cents always equals the sum of its assignments.
create or replace function assignments_payout_guard() returns trigger
language plpgsql as $$
declare
  p payouts%rowtype;
begin
  if new.payout_id is not null then
    select * into p from payouts where id = new.payout_id;
    if p.provider_id <> new.provider_id then
      raise exception 'assignment % belongs to provider %, payout % is for provider %',
        new.id, new.provider_id, p.id, p.provider_id;
    end if;
  end if;
  if tg_op = 'UPDATE' and old.payout_id is not null and old.payout_id is distinct from new.payout_id then
    select * into p from payouts where id = old.payout_id;
    if p.paid_at is not null then
      raise exception 'assignment % is in payout % which was already paid on %; cannot move it',
        old.id, p.id, p.paid_at;
    end if;
  end if;
  if tg_op = 'UPDATE' and old.payout_id is not null and old.payout_id = new.payout_id
     and old.pay_cents <> new.pay_cents then
    select * into p from payouts where id = old.payout_id;
    if p.paid_at is not null then
      raise exception 'assignment % is in a paid payout; pay_cents is frozen', old.id;
    end if;
  end if;
  return new;
end $$;
create trigger job_assignments_payout_guard
  before insert or update on job_assignments
  for each row execute function assignments_payout_guard();

create or replace function recompute_payout_total() returns trigger
language plpgsql as $$
begin
  if tg_op in ('UPDATE', 'DELETE') and old.payout_id is not null then
    update payouts set total_cents = coalesce((select sum(pay_cents) from job_assignments where payout_id = old.payout_id), 0)
      where id = old.payout_id;
  end if;
  if tg_op in ('INSERT', 'UPDATE') and new.payout_id is not null then
    update payouts set total_cents = coalesce((select sum(pay_cents) from job_assignments where payout_id = new.payout_id), 0)
      where id = new.payout_id;
  end if;
  return null;
end $$;
create trigger job_assignments_payout_total
  after insert or update or delete on job_assignments
  for each row execute function recompute_payout_total();

-- -----------------------------------------------------------------------------
-- Billing
-- -----------------------------------------------------------------------------
create table invoices (
  id                      uuid primary key default gen_random_uuid(),
  client_id               uuid not null references clients(id) on delete restrict,
  status                  invoice_status not null default 'draft',
  method                  charge_method not null default 'stripe_invoice',
  amount_cents            integer not null check (amount_cents >= 0),
  due_date                date,
  stripe_invoice_id       text unique,
  stripe_payment_link_id  text,
  stripe_checkout_url     text,
  sent_at                 timestamptz,
  paid_at                 timestamptz,
  notes                   text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now()
);
create index invoices_client_idx on invoices(client_id);
create trigger invoices_updated before update on invoices for each row execute function set_updated_at();

-- An invoice can cover several jobs (monthly commercial billing).
create table invoice_jobs (
  invoice_id  uuid not null references invoices(id) on delete cascade,
  job_id      uuid not null references jobs(id) on delete restrict,
  primary key (invoice_id, job_id)
);

-- Money actually received. Stripe rows are written by the webhook with the real fee.
create table payments (
  id                         uuid primary key default gen_random_uuid(),
  client_id                  uuid not null references clients(id) on delete restrict,
  invoice_id                 uuid references invoices(id) on delete set null,
  job_id                     uuid references jobs(id) on delete set null,   -- direct job payment (no invoice)
  method                     charge_method not null,
  amount_cents               integer not null check (amount_cents >= 0),
  fee_cents                  integer not null default 0 check (fee_cents >= 0),
  net_cents                  integer generated always as (amount_cents - fee_cents) stored,
  stripe_payment_intent_id   text unique,
  stripe_charge_id           text,
  external_ref               text,                    -- Zelle confirmation #, check number
  received_at                timestamptz not null default now(),
  notes                      text,
  created_at                 timestamptz not null default now()
);
create index payments_client_idx on payments(client_id);
create index payments_job_idx on payments(job_id);
create index payments_received_idx on payments(received_at);

-- -----------------------------------------------------------------------------
-- Expenses (the old "Expenses" tab)
-- -----------------------------------------------------------------------------
create table expenses (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,                 -- "Subscription" column
  category      expense_category not null default 'overhead',
  paid_at       date not null,                 -- "Payment Date"
  amount_cents  integer not null check (amount_cents >= 0),
  paid_with     text,                          -- "Paid With" (card / account)
  platform      text,                          -- "Platform"
  cadence       expense_cadence not null default 'one_time',  -- "Recurring Cadence"
  next_due      date,
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index expenses_paid_idx on expenses(paid_at);
create trigger expenses_updated before update on expenses for each row execute function set_updated_at();

-- -----------------------------------------------------------------------------
-- Messaging & cleaner access
-- -----------------------------------------------------------------------------
create table messages (
  id            uuid primary key default gen_random_uuid(),
  channel       message_channel not null,
  template      text not null,               -- weekly_schedule, day_before_client, job_done_nudge, unpaid_nudge, review_request...
  to_address    text not null,               -- phone or email
  provider_id   uuid references providers(id) on delete set null,
  client_id     uuid references clients(id) on delete set null,
  job_id        uuid references jobs(id) on delete set null,
  body          text not null,
  status        message_status not null default 'queued',
  external_id   text,                        -- Twilio SID / email provider id
  error         text,
  sent_at       timestamptz,
  created_at    timestamptz not null default now()
);
create index messages_job_idx on messages(job_id);
-- Prevent the same reminder going out twice for the same job.
create unique index messages_once_per_job_uq on messages(job_id, template, to_address) where job_id is not null;

-- Cleaners never log in. They get a link; the link is the credential.
create table magic_links (
  token         text primary key,            -- random 32+ bytes, base64url
  provider_id   uuid not null references providers(id) on delete cascade,
  job_id        uuid references jobs(id) on delete cascade,    -- null = "my week" link
  expires_at    timestamptz not null,
  used_at       timestamptz,
  created_at    timestamptz not null default now()
);
create index magic_links_provider_idx on magic_links(provider_id);

create table audit_log (
  id          bigint generated always as identity primary key,
  actor       text not null,                 -- 'owner', 'provider:<id>', 'system', 'claude-mcp'
  action      text not null,                 -- 'lockbox.reveal', 'payout.paid', 'job.cancel', ...
  entity      text not null,
  entity_id   uuid,
  meta        jsonb,
  created_at  timestamptz not null default now()
);
create index audit_log_entity_idx on audit_log(entity, entity_id);

create table settings (
  key         text primary key,
  value       jsonb not null,
  updated_at  timestamptz not null default now()
);
