-- -----------------------------------------------------------------------------
-- Reporting views (replace the old "Monthly Profits" tab and the per-row margin math)
-- -----------------------------------------------------------------------------
create view v_job_economics as
select
  j.id                                   as job_id,
  j.client_id,
  c.name                                 as client_name,
  j.service_type_id,
  st.name                                as cleaning_type,
  j.scheduled_start,
  j.status,
  j.charge_cents,
  j.charge_method,
  coalesce(p.received_cents, 0)          as received_cents,
  coalesce(p.fee_cents, 0)               as fee_cents,
  coalesce(a.provider_pay_cents, 0)      as provider_pay_cents,
  a.provider_names,
  coalesce(a.unpaid_assignments, 0) > 0  as provider_unpaid,
  j.charge_cents - coalesce(p.fee_cents, 0) - coalesce(a.provider_pay_cents, 0) as profit_cents,
  case when j.charge_cents > 0
       then round(100.0 * (j.charge_cents - coalesce(p.fee_cents, 0) - coalesce(a.provider_pay_cents, 0)) / j.charge_cents, 1)
       else null end                     as profit_margin_pct,
  coalesce(p.received_cents, 0) >= j.charge_cents as fully_paid
from jobs j
join clients c on c.id = j.client_id
join service_types st on st.id = j.service_type_id
left join lateral (
  select sum(amount_cents) as received_cents, sum(fee_cents) as fee_cents
  from payments where job_id = j.id
) p on true
left join lateral (
  select sum(pay_cents) as provider_pay_cents,
         string_agg(pr.name, ', ' order by pr.name) as provider_names,
         count(*) filter (where ja.payout_id is null) as unpaid_assignments
  from job_assignments ja join providers pr on pr.id = ja.provider_id
  where ja.job_id = j.id and ja.status <> 'declined'
) a on true;

-- Cash-basis monthly P&L in the business timezone.
create view v_monthly_pnl as
with months as (
  select distinct date_trunc('month', m)::date as month from (
    select received_at at time zone 'America/New_York' as m from payments
    union all select paid_at at time zone 'America/New_York' from payouts where paid_at is not null
    union all select paid_at::timestamp from expenses
  ) x
),
rec as (
  select date_trunc('month', received_at at time zone 'America/New_York')::date as month,
         sum(amount_cents) as received_cents, sum(fee_cents) as stripe_fee_cents
  from payments group by 1
),
po as (
  select date_trunc('month', paid_at at time zone 'America/New_York')::date as month,
         sum(total_cents) as provider_payment_cents
  from payouts where paid_at is not null group by 1
),
ex as (
  select date_trunc('month', paid_at)::date as month,
         sum(amount_cents) filter (where category <> 'ads') as overhead_cents,
         sum(amount_cents) filter (where category = 'ads')  as ad_cents
  from expenses group by 1
)
select
  m.month,
  coalesce(ex.overhead_cents, 0)         as overhead_expense_cents,
  coalesce(po.provider_payment_cents, 0) as provider_payment_cents,
  coalesce(rec.stripe_fee_cents, 0)      as stripe_fee_cents,
  coalesce(rec.received_cents, 0)        as received_cents,
  coalesce(ex.ad_cents, 0)               as ad_expense_cents,
  coalesce(rec.received_cents, 0) - coalesce(rec.stripe_fee_cents, 0)
    - coalesce(po.provider_payment_cents, 0) - coalesce(ex.overhead_cents, 0) - coalesce(ex.ad_cents, 0)
                                         as total_profit_cents,
  sum(coalesce(rec.received_cents, 0) - coalesce(rec.stripe_fee_cents, 0)
    - coalesce(po.provider_payment_cents, 0) - coalesce(ex.overhead_cents, 0) - coalesce(ex.ad_cents, 0))
    over (partition by date_trunc('year', m.month) order by m.month) as ytd_profit_cents
from months m
left join rec on rec.month = m.month
left join po  on po.month  = m.month
left join ex  on ex.month  = m.month
order by m.month;

-- What you owe each cleaner right now (the "Pay cleaners" screen).
create view v_provider_owed as
select
  pr.id                      as provider_id,
  pr.name                    as provider_name,
  pr.zelle_handle,
  count(ja.id)               as jobs_owed,
  coalesce(sum(ja.pay_cents), 0) as owed_cents,
  min(j.scheduled_start)     as oldest_job_at
from providers pr
join job_assignments ja on ja.provider_id = pr.id and ja.payout_id is null and ja.status = 'done'
join jobs j on j.id = ja.job_id
group by pr.id, pr.name, pr.zelle_handle;

-- Who owes you (AR aging): sent invoices not paid, plus done jobs with no payment and no invoice.
create view v_ar_aging as
select
  'invoice'::text            as kind,
  i.id                       as ref_id,
  i.client_id,
  c.name                     as client_name,
  i.amount_cents             as amount_cents,
  i.sent_at::date            as since,
  (current_date - i.sent_at::date) as days_outstanding
from invoices i join clients c on c.id = i.client_id
where i.status = 'sent'
union all
select
  'job',
  j.id,
  j.client_id,
  c.name,
  j.charge_cents,
  (j.scheduled_start at time zone 'America/New_York')::date,
  (current_date - (j.scheduled_start at time zone 'America/New_York')::date)
from jobs j join clients c on c.id = j.client_id
where j.status = 'done'
  and not exists (select 1 from payments p where p.job_id = j.id)
  and not exists (select 1 from invoice_jobs ij where ij.job_id = j.id);

-- Year-to-date paid per cleaner (1099 tracking).
create view v_provider_ytd as
select
  pr.id   as provider_id,
  pr.name as provider_name,
  pr.w9_on_file,
  extract(year from (po.paid_at at time zone 'America/New_York'))::int as year,
  sum(po.total_cents) as paid_cents
from providers pr
join payouts po on po.provider_id = pr.id and po.paid_at is not null
group by pr.id, pr.name, pr.w9_on_file, 4;

-- -----------------------------------------------------------------------------
-- Row-level security: the owner sees everything; cleaners never hit the DB
-- directly (their magic-link pages run server-side with the service role).
-- -----------------------------------------------------------------------------
create or replace function is_owner() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from profiles where user_id = auth.uid() and role = 'owner');
$$;

do $$
declare t text;
begin
  for t in
    select unnest(array['profiles','providers','clients','locations','service_types','rate_cards',
                        'leads','proposals','proposal_versions','job_series','jobs','payouts',
                        'job_assignments','invoices','invoice_jobs','payments','expenses',
                        'messages','magic_links','audit_log','settings'])
  loop
    execute format('alter table %I enable row level security', t);
    execute format('create policy %I on %I for all to authenticated using (is_owner()) with check (is_owner())',
                   t || '_owner_all', t);
  end loop;
end $$;

